#define _GNU_SOURCE
#include <sys/stat.h>
#include <sys/types.h>
#include <dlfcn.h>
#include <unistd.h>
#include <fcntl.h>

/* Pretend to be uid/gid 999 ("postgres") so PostgreSQL's root refusal and
 * data-directory ownership checks pass while running as real uid 0 in a
 * capability-less sandbox. All files are actually root-owned; stat results
 * are rewritten so uid 0 appears as 999. */
static uid_t FAKE_UID = 999;
static gid_t FAKE_GID = 999;

uid_t getuid(void)  { return FAKE_UID; }
uid_t geteuid(void) { return FAKE_UID; }
gid_t getgid(void)  { return FAKE_GID; }
gid_t getegid(void) { return FAKE_GID; }

static void fix(struct stat *b) {
    if (b->st_uid == 0) b->st_uid = FAKE_UID;
    if (b->st_gid == 0) b->st_gid = FAKE_GID;
}

typedef int (*stat_t)(const char *, struct stat *);
typedef int (*fstat_t)(int, struct stat *);
typedef int (*fstatat_t)(int, const char *, struct stat *, int);
typedef int (*xstat_t)(int, const char *, struct stat *);
typedef int (*fxstat_t)(int, int, struct stat *);
typedef int (*fxstatat_t)(int, int, const char *, struct stat *, int);

int stat(const char *p, struct stat *b) {
    static stat_t r; if (!r) r = (stat_t)dlsym(RTLD_NEXT, "stat");
    int rc = r(p, b); if (rc == 0) fix(b); return rc;
}
int lstat(const char *p, struct stat *b) {
    static stat_t r; if (!r) r = (stat_t)dlsym(RTLD_NEXT, "lstat");
    int rc = r(p, b); if (rc == 0) fix(b); return rc;
}
int fstat(int fd, struct stat *b) {
    static fstat_t r; if (!r) r = (fstat_t)dlsym(RTLD_NEXT, "fstat");
    int rc = r(fd, b); if (rc == 0) fix(b); return rc;
}
int fstatat(int d, const char *p, struct stat *b, int f) {
    static fstatat_t r; if (!r) r = (fstatat_t)dlsym(RTLD_NEXT, "fstatat");
    int rc = r(d, p, b, f); if (rc == 0) fix(b); return rc;
}
int __xstat(int v, const char *p, struct stat *b) {
    static xstat_t r; if (!r) r = (xstat_t)dlsym(RTLD_NEXT, "__xstat");
    int rc = r(v, p, b); if (rc == 0) fix(b); return rc;
}
int __lxstat(int v, const char *p, struct stat *b) {
    static xstat_t r; if (!r) r = (xstat_t)dlsym(RTLD_NEXT, "__lxstat");
    int rc = r(v, p, b); if (rc == 0) fix(b); return rc;
}
int __fxstat(int v, int fd, struct stat *b) {
    static fxstat_t r; if (!r) r = (fxstat_t)dlsym(RTLD_NEXT, "__fxstat");
    int rc = r(v, fd, b); if (rc == 0) fix(b); return rc;
}
int __fxstatat(int v, int d, const char *p, struct stat *b, int f) {
    static fxstatat_t r; if (!r) r = (fxstatat_t)dlsym(RTLD_NEXT, "__fxstatat");
    int rc = r(v, d, p, b, f); if (rc == 0) fix(b); return rc;
}
EOF
gcc -shared -fPIC -o /tmp/fakeuid.so /tmp/fakeuid.c -ldl && echo COMPILED && LD_PRELOAD=/tmp/fakeuid.so id

