#include <pwd.h>
#include <string.h>

/* getpwuid for the faked uid: return a synthetic "postgres" entry so
 * initdb/postmaster username lookups succeed without an /etc/passwd entry. */
struct passwd *getpwuid(uid_t uid) {
    static struct passwd pw;
    static char name[] = "postgres";
    static char dir[] = "/tmp";
    static char shell[] = "/bin/bash";
    if (uid == FAKE_UID) {
        pw.pw_name = name; pw.pw_passwd = (char *)"x"; pw.pw_uid = FAKE_UID;
        pw.pw_gid = FAKE_GID; pw.pw_gecos = (char *)""; pw.pw_dir = dir;
        pw.pw_shell = shell;
        return &pw;
    }
    static struct passwd *(*real)(uid_t);
    if (!real) *(void **)&real = dlsym(RTLD_NEXT, "getpwuid");
    return real(uid);
}
EOF
